INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(23501, 'Mark 10:36', 'Mark', 10, 36, '&nbsp;هغۀ ورته وفرمائيل چې، ”تاسو څۀ غواړئ چې زۀ يې درله وکړم؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23502, 'Mark 10:37', 'Mark', 10, 37, '&nbsp;هغوئ جواب ورکړو، ”مونږ له دا اجازت راکړه چې مونږ هم ستا په لويئ کښې تا سره، يو ستا ښى لاس ته او بل ګس لاس ته يو ځائ کښېنو.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23503, 'Mark 10:38', 'Mark', 10, 38, '&nbsp;عيسىٰ هغوئ ته وفرمائيل، ”تاسو چې څۀ غواړئ په هغې نۀ پوهېږئ. کوم د مصيبتونو کنډول به چې زۀ څښم ولې تاسو به هغه وڅښلے شئ؟ يا به هغه بپتسمه واخستلے شئ چې به پرې زما بپتسمه کيږى؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23504, 'Mark 10:39', 'Mark', 10, 39, '&nbsp;هغوئ جواب ورکړو چې، ”آو، مونږ يې څښلے شُو.“ بيا عيسىٰ ورته وفرمائيل چې، ”کوم کنډول چې زۀ څښم، تاسو به يې وڅښئ، او په کومه بپتسمه چې به زما بپتسمه کيږى، په هغې به ستاسو بپتسمه هم وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23505, 'Mark 10:40', 'Mark', 10, 40, '&nbsp;خو دا زما په اختيار کښې نۀ دى چې خپل ښى او ګس لاس ته څوک کښېنوم، خو دا د هغه چا دے د چا دپاره چې دا تيار کړے شوے دے.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23506, 'Mark 10:41', 'Mark', 10, 41, '&nbsp;هر کله چې نورو لسو دا واورېدل نو هغوئ يعقوب او يوحنا ته غصه شول.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23507, 'Mark 10:42', 'Mark', 10, 42, '&nbsp;عيسىٰ هغوئ ځان ته راوبلل او ورته يې وفرمائيل، ”تاسو ته پته ده چې د قومونو حکمرانان په خپلو خلقو باندې رُعب اچوى او د هغوئ لوئ آفسران په هغوئ باندې د خپل اختيار غلط استعمال کوى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23508, 'Mark 10:43', 'Mark', 10, 43, '&nbsp;خو ستاسو دپاره داسې نۀ دى. په تاسو کښې چې څوک مشرى غواړى هغه دې ستاسو خادِم شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23509, 'Mark 10:44', 'Mark', 10, 44, '&nbsp;او هر هغه څوک چې په تاسو کښې مشر کېدل غواړى هغه دې په خپله خوښه د ټولو خادِم شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23510, 'Mark 10:45', 'Mark', 10, 45, '&nbsp;ځکه چې اِبن آدم د دې دپاره رانۀغلو چې د هغۀ خِدمت دې وکړے شى خو د دې دپاره راغلو چې د نورو خِدمت وکړى او خپل ژوند د ډېرو دپاره فديه کړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23511, 'Mark 10:46', 'Mark', 10, 46, '&nbsp;خو هغوئ يريحو ته راغلل او کله چې عيسىٰ او د هغۀ مريدان د ښاريې نه ووتل نو ګڼ خلق ورپسې وُو، نو يو ړوند فقير د تمائ زوئ برتماۍ څوک چې د لارې په غاړه ناست وو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23512, 'Mark 10:47', 'Mark', 10, 47, '&nbsp;نو کله چې هغه په دې خبر شو چې دا عيسىٰ ناصرى دے نو هغۀ چغې کړې، ”اے عيسىٰ د داؤد زويه، په ما رحم وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23513, 'Mark 10:48', 'Mark', 10, 48, '&nbsp;ډېرو خلقو ورته په سختۍ ووئيل چې، ”چپ شه،“ خو هغۀ لا نورې هم چغې زياتې کړې، ”اے د داؤد زويه. په ما رحم وکړه.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23514, 'Mark 10:49', 'Mark', 10, 49, '&nbsp;عيسىٰ ودرېدلو او وې فرمائيل، ”دے دلته راولئ.“ نو هغوئ هغه ړوند سړے راوستو او ورته يې ووئيل، ”پاڅه، زړَور شه، هغه دې غواړى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23515, 'Mark 10:50', 'Mark', 10, 50, '&nbsp;په دې هغۀ خپله چُوغه وغورزوله، سمدستى پورته شو او عيسىٰ له راغلو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23516, 'Mark 10:51', 'Mark', 10, 51, '&nbsp;عيسىٰ هغۀ ته وفرمائيل، ”تۀ څۀ غواړې چې زۀ يې ستا دپاره وکړم؟“ هغه ړوند سړى جواب ورکړو، ”اُستاذه، زۀ بيا خپل نظر غواړم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23517, 'Mark 10:52', 'Mark', 10, 52, '&nbsp;عيسىٰ هغۀ ته وفرمائيل، ”لاړ شه، خپل ايمان تۀ روغ کړې،“ نو سمدستى هغه بينا شو او عيسىٰ پسې روان شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23518, 'Mark 11:1', 'Mark', 11, 1, '&nbsp;هغوئ چې يروشلم ته رانزدې شول او چې بيتِ‌فګے او بيتِ‌عنياه ته د زيتُونو غرۀ ته ورسېدل نو عيسىٰ خپل دوه مريدان د دې هداياتو سره ولېږل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23519, 'Mark 11:2', 'Mark', 11, 2, '&nbsp;”دې مخامخ کلى ته ورشئ. نو چې څنګه ورننوځئ نو تاسو به يو کوچاڼے تړلے ومومئ چې تر اوسه پرې هيچا لا سورلى نۀ ده کړې. هغه پرانيزئ او دلته يې راولئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23520, 'Mark 11:3', 'Mark', 11, 3, '&nbsp;کۀ څوک درنه تپوس وکړى چې دا څۀ کوئ؟ نو ورته ووايئ چې زمونږ د مالِک دا په کار ده او هغه به يې سمدستى دلته واپس راولېږى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23521, 'Mark 11:4', 'Mark', 11, 4, '&nbsp;هغوئ لاړل او د دروازې نه بهر يې په کوڅه کښې هغه کوچاڼے تړلے وموندلو. هغوئ هغه پرانستو،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23522, 'Mark 11:5', 'Mark', 11, 5, '&nbsp;او په ولاړو خلقو کښې ځينو ورته ووئيل چې، ”دا څۀ کوئ؟ تاسو دا کوچاڼے ولې پرانيزئ؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23523, 'Mark 11:6', 'Mark', 11, 6, '&nbsp;نو هغوئ هغه جواب ورکړو څۀ چې ورته عيسىٰ فرمائيلى وُو، نو بيا يې هغوئ پرېښودل چې بو يې ځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23524, 'Mark 11:7', 'Mark', 11, 7, '&nbsp;نو هغوئ عيسىٰ له کوچاڼے راوستو او خپلې جامې يې پرې واچولې او هغه پرې سور شو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23525, 'Mark 11:8', 'Mark', 11, 8, '&nbsp;او ډېرو خلقو ورته په لارو کښې خپلې جامې وغوړولې او نورو د پټو نه څانګې پرېکړلې او ورته يې خورې کړلې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23526, 'Mark 11:9', 'Mark', 11, 9, '&nbsp;او څومره خلق چې مخکښې تلل او هغه چې وروستو راتلل، نو بيا څوک چې د هغۀ نه وړاندې تلل او څوک چې ورپسې روان وُو هغوئ چغې ويستلې چې، ”اُمبارکى د هغه چا چې د مالِک خُدائ په نوم راځى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23527, 'Mark 11:10', 'Mark', 11, 10, '&nbsp;زمونږ د پلار نيکۀ داؤد راتلونکې بادشاهى دې مبارکه وى. په آسمان کښې دې په هغۀ مبارکى وى.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23528, 'Mark 11:11', 'Mark', 11, 11, '&nbsp;هغه يروشلم ښار ته راغلو او د خُدائ کور ته ورننوتو او ګېرچاپېره يې وکتل، خو ماښام ناوخته هغه د دولسو مريدانو سره بيتِ‌عنياه ته لاړو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23529, 'Mark 11:12', 'Mark', 11, 12, '&nbsp;په بله ورځ چې هغوئ د بيتِ‌عنياه نه ووتل نو عيسىٰ اوږے شوے وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23530, 'Mark 11:13', 'Mark', 11, 13, '&nbsp;او د لرې نه يې چې د اينځر يوه ونه وليده نو ورغلو چې هغه په کښې څۀ پېدا کړى. خو کله چې هغه ورغے نو د پاڼو نه بغېر يې په کښې هيڅ ونۀ موندل ځکه چې دا د اينځرو موسم نۀ وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23531, 'Mark 11:14', 'Mark', 11, 14, '&nbsp;هغه ونې ته يې وفرمائيل چې، ”بيا به هيڅوک هم هيڅکله ستا نه مېوه ونۀ خورى.“ او د هغۀ مريدانو دا واورېدل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23532, 'Mark 11:15', 'Mark', 11, 15, '&nbsp;کله چې هغوئ يروشلم ته راغلل نو عيسىٰ بيا د خُدائ کور ته ورننوتو او هغه ټول خلق چې د خُدائ په کور کښې يې سوداګرى کوله وشړل. او هغه د صرافانو تختې او د کونترو د خرڅوونکو کُرسۍ يې نسکورې کړې.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23533, 'Mark 11:16', 'Mark', 11, 16, '&nbsp;او د خُدائ د کور په دربار کښې هغۀ د تجارت د څيزونو وړل راوړل نۀ پرېښودل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23534, 'Mark 11:17', 'Mark', 11, 17, '&nbsp;نو بيا يې هغوئ ته تعليم شروع کړو او وې فرمائيل، ”ولې صحيفې دا نۀ وائى چې، زما کور به د ټولو قومونو دپاره د دُعا کور بللے شى؟ خو تاسو ترې د ډاکوانو اډه جوړه کړې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23535, 'Mark 11:18', 'Mark', 11, 18, '&nbsp;مشرانو اِمامانو او د شرعې عالمانو چې دا واورېدل نو کوشش يې کولو چې هغه په څۀ چل هلاک کړى خو هغوئ يرېدل ځکه چې ټول خلق د هغۀ د تعليم نه ډېر متاثره وُو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23536, 'Mark 11:19', 'Mark', 11, 19, '&nbsp;او چې ماښام شو نو عيسىٰ او د هغۀ مريدان د ښار نه بهر ووتل.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23537, 'Mark 11:20', 'Mark', 11, 20, '&nbsp;بله ورځ سحر وختى چې هغوئ په لاره تېرېدل نو هغوئ وليدل چې هغه د اينځر ونه له بېخ نه اوچه شوې ده.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23538, 'Mark 11:21', 'Mark', 11, 21, '&nbsp;پطروس هغه خبره راياده کړه کومه چې عيسىٰ پرون د اينځر ونې ته کړې وه نو هغۀ ووئيل، ”اُستاذه، وګوره د اينځر په کومه ونه چې تا لعنت کړے وو هغه اوچه شوې ده.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23539, 'Mark 11:22', 'Mark', 11, 22, '&nbsp;عيسىٰ ورته جواب ورکړو چې، ”په خُدائ پاک ايمان ساتئ.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23540, 'Mark 11:23', 'Mark', 11, 23, '&nbsp;زۀ تاسو ته رښتيا وايم چې کۀ څوک دې غر ته ووائى چې د دې خپل ځايه اوچت شه او سمندر کښې وغورزېږه، او په زړۀ کښې يې شک نۀ وى او ايمان ساتى، نو هر څۀ چې وائى هغه به د هغۀ دپاره وشى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23541, 'Mark 11:24', 'Mark', 11, 24, '&nbsp;ځکه زۀ تاسو ته وايم، تاسو چې د څۀ دپاره هم دُعا کوئ نو ايمان ساتئ چې دا تاسو حاصل کړو نو هغه به ستاسو شى.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23542, 'Mark 11:27', 'Mark', 11, 27, '&nbsp;هغوئ يو ځل بيا يروشلم ته راغلل او کله چې عيسىٰ د خُدائ په کور کښې ګرځېدو نو مشران اِمامان، د شرعې عالمان او د قوم مشران ورته راغلل،', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23543, 'Mark 11:28', 'Mark', 11, 28, '&nbsp;او ورته وې وئيل، ”تۀ دا کارونه په کوم اختيار کوې؟ او دا اختيار تا له چا درکړے دے چې تۀ داسې کوه؟“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23544, 'Mark 11:29', 'Mark', 11, 29, '&nbsp;عيسىٰ هغوئ ته وفرمائيل، ”زۀ هم ستاسو نه يو تپوس کوم، تاسو يې جواب راکړئ نو زۀ به هم تاسو ته دا وښايم چې په کوم اختيار زۀ دا کارونه کوم.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23545, 'Mark 11:30', 'Mark', 11, 30, '&nbsp;د يحيىٰ بپتسمه د آسمان د لورى وه او کۀ د انسان نه؟ جواب راکړئ.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23546, 'Mark 11:31', 'Mark', 11, 31, '&nbsp;په دې هغوئ د يو بل سره په بحث شول چې، ”مونږ څۀ ووايو؟ کۀ چرې مونږ ووايو چې له آسمان نه، نو هغه به راته ووائى چې بيا تاسو په هغۀ ايمان ولې رانۀ وړو؟', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23547, 'Mark 11:32', 'Mark', 11, 32, '&nbsp;او کۀ مونږ وايو چې د انسانانو نه، نو بيا به څۀ وشى؟“ دوئ د خلقو نه يرېدل ځکه چې د ټولو خلقو دا ايمان وو چې يحيىٰ نبى وو.', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(23548, 'Mark 11:33', 'Mark', 11, 33, '&nbsp;نو ځکه هغوئ جواب ورکړو چې، ”مونږ خبر نۀ يُو.“ او عيسىٰ ورته وفرمائيل چې، ”بيا به زۀ هم درته ونۀ وايم چې زۀ په کوم اختيار دا کارونه کوم.“', '', 'NT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
